changeSet.sql:
ALTER TABLE stored_files ADD COLUMN strip_metadata boolean NOT NULL DEFAULT false;
COMMENT ON COLUMN stored_files.strip_metadata IS
    'The uploading module asked for an image''s metadata (GPS, camera, dates) to be removed at confirmation, keeping only its orientation. The cleaned file replaces the original under a new key.';

CREATE TABLE estate_photos (
    id          uuid NOT NULL PRIMARY KEY,
    tenant_id   uuid NOT NULL REFERENCES organizations (id),
    branch_id   uuid REFERENCES branches (id),
    created_at  timestamp(6) with time zone NOT NULL,
    updated_at  timestamp(6) with time zone,
    created_by  varchar(255),
    updated_by  varchar(255),
    deleted     boolean NOT NULL,

    estate_id   uuid NOT NULL REFERENCES estates (id),
    file_id     uuid NOT NULL REFERENCES stored_files (id),
    caption     varchar(200),
    position    integer NOT NULL,
    cover       boolean NOT NULL,

    CONSTRAINT chk_estate_photos_position CHECK (position >= 0)
);
CREATE INDEX idx_estate_photos_estate ON estate_photos (estate_id, position) WHERE deleted = false;
CREATE UNIQUE INDEX uq_estate_photos_file ON estate_photos (file_id) WHERE deleted = false;
CREATE UNIQUE INDEX uq_estate_photos_one_cover ON estate_photos (estate_id) WHERE cover AND deleted = false;
REVOKE DELETE, TRUNCATE ON estate_photos FROM ${appDbUsername};
COMMENT ON TABLE estate_photos IS
    'An estate''s photos, in order, one the cover. Public: shown on the marketplace while the estate is listed. Soft-deleted only. See AGENTS.md, "Estate photos".';
COMMENT ON COLUMN estate_photos.caption IS
    'Shown with the photo and used as its alt text. Published.';

ALTER TABLE estate_photos ENABLE ROW LEVEL SECURITY;
ALTER TABLE estate_photos FORCE ROW LEVEL SECURITY;
CREATE POLICY estate_photos_platform ON estate_photos FOR ALL
    USING (current_setting('landvault.platform_scope', true) = 'on')
    WITH CHECK (current_setting('landvault.platform_scope', true) = 'on');
CREATE POLICY estate_photos_tenant ON estate_photos FOR ALL
    USING (
        current_setting('landvault.tenant_id', true) IS NOT NULL
        AND current_setting('landvault.tenant_id', true) != ''
        AND tenant_id::text = current_setting('landvault.tenant_id', true)
        AND (
            current_setting('landvault.branch_id', true) IS NULL
            OR current_setting('landvault.branch_id', true) = ''
            OR branch_id IS NULL
            OR branch_id::text = current_setting('landvault.branch_id', true)
        )
    )
    WITH CHECK (
        current_setting('landvault.tenant_id', true) IS NOT NULL
        AND current_setting('landvault.tenant_id', true) != ''
        AND tenant_id::text = current_setting('landvault.tenant_id', true)
        AND (
            current_setting('landvault.branch_id', true) IS NULL
            OR current_setting('landvault.branch_id', true) = ''
            OR branch_id IS NULL
            OR branch_id::text = current_setting('landvault.branch_id', true)
        )
    );

ALTER TABLE estates ADD COLUMN photo_requirement_exempt boolean NOT NULL DEFAULT false;
UPDATE estates SET photo_requirement_exempt = true
 WHERE published = true AND deleted = false;
COMMENT ON COLUMN estates.photo_requirement_exempt IS
    'One-time grandfathering: true for estates already published when the photo requirement shipped (changeset 086). They keep their listing without a photo. TODO: once they have photos, clear the flag and drop this column and its term in marketplace_estate_eligibility.';
